ALTER TABLE YoutubeMember ADD COLUMN archivedAt DATETIME;
ALTER TABLE YoutubePayment ADD COLUMN assignmentMemberId TEXT;
ALTER TABLE YoutubePayment ADD COLUMN voidedAt DATETIME;
ALTER TABLE YoutubeLedgerEntry ADD COLUMN voidedAt DATETIME;
ALTER TABLE YoutubeLedgerEntry ADD COLUMN updatedAt DATETIME NOT NULL DEFAULT '2026-10-21 00:00:00';
CREATE TABLE YoutubeRecordHistory (id TEXT NOT NULL PRIMARY KEY, entityType TEXT NOT NULL, entityId TEXT NOT NULL, action TEXT NOT NULL, beforeJson TEXT, afterJson TEXT, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX YoutubeRecordHistory_entityType_entityId_createdAt_idx ON YoutubeRecordHistory(entityType,entityId,createdAt);
UPDATE YoutubePayment SET assignmentMemberId=(SELECT memberId FROM YoutubeBillingSeat WHERE id=YoutubePayment.seatId);
INSERT INTO YoutubeRecordHistory(id,entityType,entityId,action,afterJson) SELECT lower(hex(randomblob(16))),'GROUP',id,'BASELINE',json_object('id',YoutubeBillingGroup.id,'importKey',YoutubeBillingGroup.importKey,'name',YoutubeBillingGroup.name,'dueDay',YoutubeBillingGroup.dueDay,'status',YoutubeBillingGroup.status,'createdAt',YoutubeBillingGroup.createdAt,'updatedAt',YoutubeBillingGroup.updatedAt,'monthlyPriceSatang',YoutubeBillingGroup.monthlyPriceSatang,'startedOn',YoutubeBillingGroup.startedOn,'openingReceivedSatang',YoutubeBillingGroup.openingReceivedSatang) FROM YoutubeBillingGroup;
